#!/usr/bin/env python3
"""
Round 198o (culprits), 14 October 2026. Needs round 197o.

Layers box rearranged; city maps dragged; the combine reads tiled layers worldwide.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 198o (14 October)\n\nNeeds round 197o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Layers box (asked 14 October), kept in order by layersBoxOrder (a\n  MutationObserver, since parts arrive at different times): the head\n  (Layers, How to Use, All on, All off), the How to Use box (closed until\n  clicked; the owner\'s own wording), All Points / All Shapes / All National\n  Highlights on one line (no "Turn on every"), then Pull all layers up and\n  "Shading where points crowd" (DENSITY_ON, kept in localStorage\n  culprits-density; densityBandsShow obeys it), the list, then Search,\n  Combine the ticked layers and Layer colours. Reset layers menu is gone\n  (resetRows stays, unused). All on and All off ask first (askFirst); All\n  off also pulls up every dropdown (pullAllUp, which Pull all layers up runs\n  alone).\n- The four Clark Labs pond maps are filed under Meat > Marine meats > Fish\n  and shrimp farms as well as Oceans > Fishing (their "ponds" bundle had sat\n  empty under Meat).\n- Atlas city maps open large in the middle of the screen; the button makes\n  them small in the corner. The picture is dragged to move round it (a\n  click still zooms), and the box is dragged by its top bar.\n- Combine: tiled layers are now read worldwide (comboWorld): each PMTiles\n  archive read whole at zoom 4 (or the archive\'s own nearest), decoded by\n  mvtDecode (checked against @mapbox/vector-tile in the sandbox), and used\n  in place of what the view had shown, so nothing counts twice. Rows over\n  400,000 features at that zoom, or not from an archive, are read as before\n  and named in the message. At zoom 4 features are held to about 600 m, and\n  archives that draw squares of counts at that zoom are counted as squares.\n  Wording: with each layer in its own group the text speaks of layers, not\n  groups; the group list has a heading ("Which layers count together"); the\n  shares say in full what they measure; the repeated sentences are gone.\n- News wires: work in the sandbox with every feed file (all 34 read and\n  shown); a third address (each feed repo\'s Pages copy) added to try.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round198o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 197o" not in h.read_text(encoding="utf-8"):
        sys.exit("round198o: round 197o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round198o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/test.mjs", "map/wire.js", check=False)
            sys.exit("round198o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round198o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
